package h3

import (
	"strconv"
	"testing"
)

func BenchmarkNumCells(b *testing.B) {
	for r := 0; r <= MaxResolution; r++ {
		b.Run(strconv.Itoa(r), func(b *testing.B) {
			for b.Loop() {
				NumCells(r)
			}
