		checkMeasure(t, "EdgeLengthKm", record.LengthKm, km, tolerances, measure(h3go.EdgeLengthKm(edge)))
		checkMeasure(t, "EdgeLengthM", record.LengthM, m, tolerances, measure(h3go.EdgeLengthM(edge)))

		boundary, err := edge.Boundary()
